const body = $input.first().json.body || $input.first().json;
const chatInput = body.chatInput || body.message || body.requirements || '';
const isSystemPrompt = chatInput.includes('[Auto-Tag]') || chatInput.includes('[Follow-Up Questions]') || chatInput.includes('[Title Generation]');
let systemPromptType = null;
if (chatInput.includes('[Auto-Tag]')) systemPromptType = 'auto-tag';
else if (chatInput.includes('[Follow-Up Questions]')) systemPromptType = 'follow-up';
else if (chatInput.includes('[Title Generation]')) systemPromptType = 'title-gen';
return [{ json: { rawInput: chatInput, projectSlug: body.projectSlug || body.project_slug || null, projectName: body.projectName || body.project_name || null, requirements: body.requirements || null, sessionId: body.sessionId || body.session_id || null, isSystemPrompt, systemPromptType } }];

const type = $input.first().json.systemPromptType;
let response = {};
if (type === 'auto-tag') { response = { tags: ['software-delivery', 'architecture'] }; }
else if (type === 'follow-up') { response = { questions: ['What specific aspects would you like to explore?'] }; }
else if (type === 'title-gen') { response = { title: 'Delivery Manager Assistant' }; }
return [{ json: response }];

const response = $input.first().json;
const parsed = $('Parse Input').first().json;
let classification = { mode: 'chat', intent: 'help' };
try { const content = response.message?.content; if (content) classification = JSON.parse(content); } catch (e) {}
return [{ json: { ...parsed, mode: classification.mode || 'chat', intent: classification.intent || 'help', extractedProjectSlug: classification.projectSlug || null } }];

const input = $input.first().json;
const intent = input.intent || 'help';
const projectSlug = input.projectSlug || input.extractedProjectSlug;
let response = { agent: 'Delivery Manager', stage: 'software-delivery', intent: intent, action: 'direct_response', query: null };
switch(intent) {
  case 'help':
    response.content = '# Software Delivery Pipeline\\n\\n## Commands\\n| Command | Description |\\n|---------|-------------|\\n| help | Show help |\\n| status | Check job status |\\n| artifacts | List artifacts |\\n| jobs | List recent jobs |\\n| list | List projects |';
    response.message = 'Help';
    break;
  case 'status': case 'jobs':
    response.action = 'query_db';
    response.query = projectSlug ? `SELECT j.id, p.slug as project, j.stage, j.status, j.created_at, j.completed_at FROM architecture.jobs j JOIN architecture.projects p ON j.project_id = p.id WHERE j.stage = 'software-delivery' AND p.slug = '${projectSlug}' ORDER BY j.created_at DESC LIMIT 10` : `SELECT j.id, p.slug as project, j.stage, j.status, j.created_at, j.completed_at FROM architecture.jobs j JOIN architecture.projects p ON j.project_id = p.id WHERE j.stage = 'software-delivery' ORDER BY j.created_at DESC LIMIT 10`;
    response.queryType = 'jobs';
    break;
  case 'artifacts':
    response.action = 'query_db';
    response.query = `SELECT a.id, p.slug as project, a.artifact_type, a.version, a.created_at FROM architecture.artifacts a JOIN architecture.projects p ON a.project_id = p.id WHERE a.artifact_type LIKE 'delivery_%' ORDER BY a.created_at DESC LIMIT 10`;
    response.queryType = 'artifacts';
    break;
  case 'list':
    response.action = 'query_db';
    response.query = 'SELECT p.id, p.slug, p.name, p.created_at FROM architecture.projects p ORDER BY p.created_at DESC LIMIT 20';
    response.queryType = 'projects';
    break;
  default:
    response.content = 'Unknown command. Try help.';
    response.message = 'Unknown';
}
return [{ json: response }];

const chatContext = $('Chat Handler').first().json;
const queryResults = $input.all().map(i => i.json);
let content = '';
const queryType = chatContext.queryType;
if (queryResults.length === 0) { content = 'No results found.'; }
else {
  switch(queryType) {
    case 'jobs':
      content = '# Jobs\\n\\n| ID | Project | Stage | Status | Created | Completed |\\n|----|---------|-------|--------|---------|-----------|\\n';
      for (const row of queryResults) { content += `| ${row.id?.substring(0,8)}... | ${row.project} | ${row.stage} | ${row.status} | ${new Date(row.created_at).toLocaleDateString()} | ${row.completed_at ? new Date(row.completed_at).toLocaleDateString() : '-'} |\\n`; }
      break;
    case 'artifacts':
      content = '# Artifacts\\n\\n| ID | Project | Type | Version | Created |\\n|----|---------|------|---------|---------|\\n';
      for (const row of queryResults) { content += `| ${row.id?.substring(0,8)}... | ${row.project} | ${row.artifact_type} | ${row.version} | ${new Date(row.created_at).toLocaleDateString()} |\\n`; }
      break;
    case 'projects':
      content = '# Projects\\n\\n| Slug | Name | Created |\\n|------|------|---------|\\n';
      for (const row of queryResults) { content += `| ${row.slug} | ${row.name} | ${new Date(row.created_at).toLocaleDateString()} |\\n`; }
      break;
    default: content = JSON.stringify(queryResults, null, 2);
  }
}
return [{ json: { agent: 'Delivery Manager', stage: 'software-delivery', intent: chatContext.intent, success: true, content: content, message: `Found ${queryResults.length} result(s)`, rowCount: queryResults.length } }];

const init = $('Initialize Parameters').first().json;
const project = $('Load Project').first().json;
const pmJob = $('Get Latest PM Job').first().json;
const job = $json;
return [{ json: { projectId: project.id, projectSlug: project.slug, projectName: project.name || project.slug, jobId: job.id, inputJobId: pmJob?.id || null } }];

const ctx = $('Pass Context').first().json;
const rows = $input.all().map(i => i.json);
const byType = {};
for (const r of rows) byType[r.type] = r.content;

const prdMd = byType.prd_md?.markdown || '';
const brd = byType.brd || {};

if (!prdMd) throw new Error('Missing PRD artifact for project ' + ctx.projectSlug);

return [{ json: { ...ctx, prdMarkdown: prdMd, brd } }];

const ctx = $json;
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;

const repoDir = '/opt/workspace/software-delivery';
const projectDir = repoDir + '/' + projectSlug + '-docs';
const remote = 'git@github.com:shlapolosa/software-delivery.git';

let sh = 'set -e\n';
sh += 'mkdir -p /opt/workspace\n';
sh += "if [ ! -d '" + repoDir + "/.git' ]; then git clone '" + remote + "' '" + repoDir + "'; fi\n";
sh += "cd '" + repoDir + "'\n";
sh += "git remote set-url origin '" + remote + "'\n";
sh += 'git fetch origin\n';
sh += "git checkout -B '" + projectSlug + "' 'origin/" + projectSlug + "' 2>/dev/null || git checkout -B '" + projectSlug + "'\n";
sh += "mkdir -p '" + projectDir + "/docs'\n";

// Write PRD.md if needed
sh += "cat > '" + projectDir + "/docs/PRD.md' <<'EOF_" + jobId + "'\n";
sh += ctx.prdMarkdown + "\nEOF_" + jobId + "\n";

sh += "git add '" + projectSlug + "-docs/docs/PRD.md'\n";
sh += "git commit -m 'Update PRD for " + projectSlug + " (job " + jobId + ")' || true\n";
sh += "git push -u origin '" + projectSlug + "'\n";

return [{ json: { ...ctx, gitScript: sh } }];

const ctx = $('Pass Context').first().json;
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;

const remote = 'git@github.com:shlapolosa/software-delivery.git';
const repoDir = '/opt/workspace/software-delivery';
const projectDir = repoDir + '/' + projectSlug + '-docs';
const containerWorkDir = '/tmp/taskmaster-work/' + projectSlug;

let sh = 'set -e\n';

// Clone and checkout the repo
sh += "if [ ! -d '" + repoDir + "/.git' ]; then git clone '" + remote + "' '" + repoDir + "'; fi\n";
sh += "cd '" + repoDir + "'\n";
sh += "git remote set-url origin '" + remote + "'\n";
sh += 'git fetch origin --prune\n';
sh += "git checkout -B '" + projectSlug + "' 'origin/" + projectSlug + "' 2>/dev/null || git checkout -B '" + projectSlug + "'\n";
sh += "git pull origin '" + projectSlug + "' || true\n";

// Verify PRD exists
sh += "test -f '" + projectDir + "/docs/PRD.md' || { echo 'ERROR: PRD.md not found'; exit 1; }\n";

// Create container work directory and copy PRD using docker cp
sh += "docker exec taskmaster rm -rf '" + containerWorkDir + "' || true\n";
sh += "docker exec taskmaster mkdir -p '" + containerWorkDir + "/docs'\n";
sh += "docker cp '" + projectDir + "/docs/PRD.md' 'taskmaster:" + containerWorkDir + "/docs/PRD.md'\n";

// Run taskmaster commands inside container
sh += "docker exec -w '" + containerWorkDir + "' taskmaster task-master init -y || true\n";

// Configure taskmaster to use Ollama models - write config to temp file and docker cp
const configJson = JSON.stringify({
  models: {
    main: { provider: 'ollama', modelId: 'llama3.1:8b-instruct-q4_K_M' },
    fallback: { provider: 'ollama', modelId: 'llama3.1:8b-instruct-q4_K_M' },
    research: { provider: 'ollama', modelId: 'llama3.1:8b-instruct-q4_K_M' }
  },
  global: { ollamaBaseUrl: 'http://ollama:11434/api' }
}, null, 2);
const configTmpFile = '/tmp/taskmaster-config-' + jobId + '.json';
sh += "cat > '" + configTmpFile + "' << 'EOFCONFIG'\n" + configJson + "\nEOFCONFIG\n";
sh += "docker cp '" + configTmpFile + "' 'taskmaster:" + containerWorkDir + "/.taskmaster/config.json'\n";
sh += "rm -f '" + configTmpFile + "'\n";

sh += "docker exec -w '" + containerWorkDir + "' taskmaster task-master parse-prd --input='docs/PRD.md' --num-tasks=15\n";
sh += "for i in 1 2 3 4 5; do docker exec -w '" + containerWorkDir + "' taskmaster task-master analyze-complexity || true; docker exec -w '" + containerWorkDir + "' taskmaster task-master expand --all --force || break; done\n";
sh += "docker exec -w '" + containerWorkDir + "' taskmaster task-master analyze-complexity || true\n";

// Copy tasks.json back from container
sh += "mkdir -p '" + projectDir + "/backlog'\n";
sh += "docker cp 'taskmaster:" + containerWorkDir + "/.taskmaster/tasks/tasks.json' '" + projectDir + "/backlog/tasks.json' || { echo 'WARNING: tasks.json not found'; }\n";

// Commit and push
sh += "cd '" + repoDir + "'\n";
sh += "git add '" + projectSlug + "-docs/backlog/' || true\n";
sh += "git commit -m 'Add taskmaster tasks for " + projectSlug + " (job " + jobId + ")' || true\n";
sh += "git push origin '" + projectSlug + "'\n";

// Cleanup container work directory
sh += "docker exec taskmaster rm -rf '" + containerWorkDir + "' || true\n";

return [{ json: { ...ctx, taskmasterScript: sh } }];

// Software Delivery Chat Handler
const agentConfig = {
  name: 'Software Delivery Engineer',
  shortName: 'software-delivery',
  collectionName: 'agent-knowledge-software-delivery',
  folder: 'agent-docs/software-delivery',
  helpFile: '/data/shared/knowledge/agent-docs/software-delivery/help.md'
};

const input = $input.all()[0].json;
const intent = input.intent || 'help';
const query = input.query || '';

let response = {
  agent: agentConfig.name,
  intent: intent,
  success: true
};

switch (intent) {
  case 'help':
    response.content = `# ${agentConfig.name} Agent Help\n\n## Available Commands\n\n| Intent | Description |\n|--------|-------------|\n| help | Show this help message |\n| status | Check knowledge base status |\n| list | List documents in knowledge base |\n| upload | Upload a document to knowledge base |\n| reload | Reload all documents in knowledge base |\n| query | Query the knowledge base |\n\n## Knowledge Base\n- Collection: ${agentConfig.collectionName}\n- Folder: ${agentConfig.folder}\n\n## Delivery Domains\n- CI/CD Pipeline Design\n- Deployment Automation\n- Infrastructure as Code\n- Task Master Integration\n`;
    response.message = `${agentConfig.name} Help`;
    break;

  case 'status':
    response.action = 'query_qdrant_status';
    response.collection = agentConfig.collectionName;
    break;

  case 'list':
    response.action = 'query_qdrant_list';
    response.collection = agentConfig.collectionName;
    break;

  case 'upload':
    response.action = 'call_knowledge_loader';
    response.loaderPayload = {
      action: 'upload',
      collection: agentConfig.collectionName,
      folder: agentConfig.folder,
      content: input.content || '',
      filename: input.filename || ''
    };
    break;

  case 'reload':
    response.action = 'call_knowledge_loader';
    response.loaderPayload = {
      action: 'reload',
      collection: agentConfig.collectionName,
      folder: agentConfig.folder
    };
    break;

  case 'query':
    response.action = 'rag_query';
    response.collection = agentConfig.collectionName;
    response.query = query;
    break;

  default:
    response.success = false;
    response.errorMessage = `Unknown intent: ${intent}. Valid intents: help, status, list, upload, reload, query`;
}

return [{ json: response }];

// Build Azure DevOps push payload
const ctx = $('Build Git Script').first().json;
const repoInfo = $json;
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;

// Get artifact content - try common variable names
const artifactContent = ctx.prdMarkdown || ctx.artifactMarkdown || ctx.content || '';
const artifactPath = "/docs/PRD.md";

// Determine branch reference
const branchName = `refs/heads/${projectSlug}`;

// For new branches, use all zeros as oldObjectId
const oldObjectId = '0000000000000000000000000000000000000000';

// Build the push payload
const changes = [{
  changeType: 'add',
  item: { path: `/${projectSlug}-docs${artifactPath}` },
  newContent: {
    content: Buffer.from(artifactContent).toString('base64'),
    contentType: 'base64encoded'
  }
}];

return [{
  json: {
    ...ctx,
    azurePushPayload: {
      refUpdates: [{
        name: branchName,
        oldObjectId: oldObjectId
      }],
      commits: [{
        comment: `Add artifacts for ${projectSlug} (job ${jobId})`,
        changes: changes
      }]
    },
    azureRepoInfo: repoInfo
  }
}];
